Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Bounding surface
  <select id="selSurface">
    <option value="All" selected>All</option>
    <option value="cap">Paraboloid cap</option>
    <option value="wall">Cylinder wall</option>
