  </select>
</label>
<label>cap z = <input type="text" id="capEq" value="4 - x*x - y*y" style="width:130px"></label>
<label>cylinder (x − h)² + y² = 1, h = <input type="text" id="cylEq" value="1" style="width:60px"></label>
<div style="display:flex;gap:4px;">
  <button id="btnPrev">◀ Step</button>
  <button id="btnNext">Step ▶</button>
</div>
<div id="stepNarration" style="font-size:11px;max-width:220px;color:#333;background:#fff;padding:4px;border:1px solid #ddd;border-radius:4px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Element spec:
// paraboloid cap → custom radial BufferGeometry, vertex colors blue(#5b8fc4)→orange(#d2691e) by height
// cylinder wall  → custom parametric grid, Lambert #7aa8d8 opacity 0.55, double-sided, clipped at cap
// intersection curve → THREE.LineLoop, z = capFn(h+cos t, sin t), color #cc3300
// base disk → CircleGeometry r=1 at (h,0), flat #4f86c6, in xy-plane (world XZ)
// axes → black Lines + ConeGeometry arrowheads; z = world Y, math (x,y,z) → world (x, z, y)
// dashed z-axis inside solid → LineDashedMaterial 0→cap(0,0); solid above with arrowhead
// slice → translucent lens mesh (polar grid clipped by fn>=z), color #e0a030
// labels → addLabel: x, y, z, 0, 2, z = 4-x²-y² (with 3D arrow), (x-1)²+y²=1 (curved 3D arrow)

const M = (x, y, z) => new THREE.Vector3(x, z, y); // math → world (y-up)
let capFn = (x, y) => 4 - x * x - y * y;
let hCyl = 1;

scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.9);
dirLight.position.set(3, 6, 4);
scene.add(dirLight);

const C_BLUE = new THREE.Color(0x5b8fc4), C_ORANGE = new THREE.Color(0xd2691e);

// ---------- materials ----------
const capMat = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide });
const wallMat = new THREE.MeshLambertMaterial({ color: 0x7aa8d8, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
const diskMat = new THREE.MeshLambertMaterial({ color: 0x4f86c6, transparent: true, opacity: 0.95, side: THREE.DoubleSide });
const curveMat = new THREE.LineBasicMaterial({ color: 0xcc3300 });
const sliceMat = new THREE.MeshBasicMaterial({ color: 0xe0a030, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false });
const rimMat = new THREE.LineBasicMaterial({ color: 0x2f6fb4 });

let capMesh = null, wallMesh = null, curveLine = null, diskMesh = null, rimLine = null, sliceMesh = null;

function addOrReplace(obj, prev) {
  if (prev) { scene.remove(prev); _disposeObject(prev); }
  scene.add(obj);
  return obj;
}

// ---------- cap ----------
function buildCap() {
  const z0 = capFn(0, 0);
  if (!(z0 > 0)) { if (capMesh) { scene.remove(capMesh); capMesh = null; } return; }
  const NT = 96, NR = 40;
  const pos = [], col = [], idx = [];
  const tmpC = new THREE.Color();
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    // bisect for r where fn = 0 along this ray
    let lo = 0, hi = 3.0, rMax = 3.0;
    if (capFn(hi * c, hi * s) > 0) { rMax = hi; }
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (capFn(m * c, m * s) > 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      const x = r * c, y = r * s;
      const z = Math.max(0, capFn(x, y));
      pos.push(x, z, y);
      tmpC.copy(C_BLUE).lerp(C_ORANGE, Math.min(1, z / z0));
      col.push(tmpC.r, tmpC.g, tmpC.b);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  capMesh = addOrReplace(new THREE.Mesh(g, capMat), capMesh);
}

// ---------- cylinder wall (clipped at cap) ----------
function buildWall() {
  const NT = 96, NZ = 10;
  const pos = [], idx = [];
  const ztops = [];
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    const zt = Math.max(0.001, capFn(x, y));
    ztops.push(zt);
    for (let j = 0; j <= NZ; j++) {
      pos.push(x, zt * (j / NZ), y);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NZ; j++) {
    const a = i * (NZ + 1) + j, b = a + NZ + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  wallMesh = addOrReplace(new THREE.Mesh(g, wallMat), wallMesh);

  // bright rim at open top
  const rp = [];
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    rp.push(new THREE.Vector3(x, Math.max(0.001, capFn(x, y)), y));
  }
  rimLine = addOrReplace(new THREE.Line(rp.length ? new THREE.BufferGeometry().setFromPoints(rp) : new THREE.BufferGeometry(), rimMat), rimLine);
}

// ---------- intersection curve ----------
function buildCurve() {
  const pts = [];
  for (let i = 0; i < 128; i++) {
    const t = (i / 128) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    const z = capFn(x, y);
    if (z > 0) pts.push(new THREE.Vector3(x, z, y));
  }
  const g = pts.length > 2 ? new THREE.BufferGeometry().setFromPoints(pts) : new THREE.BufferGeometry();
  curveLine = addOrReplace(new THREE.LineLoop(g, curveMat), curveLine);
}

// ---------- base disk ----------
function buildDisk() {
  const g = new THREE.CircleGeometry(1, 72);
  g.rotateX(-Math.PI / 2); // lie in world XZ (math xy-plane)
  const m = new THREE.Mesh(g, diskMat);
  m.position.set(hCyl, 0.005, 0);
  diskMesh = addOrReplace(m, diskMesh);
}

function rebuildAll() {
  buildCap(); buildWall(); buildCurve(); buildDisk(); buildSlice();
  updateVisibility();
}

// ---------- slice cross-section ----------
let sliceZ = 0;
function buildSlice() {
  if (sliceMesh) { scene.remove(sliceMesh); _disposeObject(sliceMesh); sliceMesh = null; }
  if (sliceZ <= 0) return;
  const NR = 48, NT = 144;
  const pos = [], idx = [];
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    // bisect radius where capFn = sliceZ along this ray (from disk center)
    let lo = 0, hi = 1, rMax = 1;
    const fAt = (r) => capFn(hCyl + r * c, r * s) - sliceZ;
    if (fAt(hi) >= 0) rMax = hi;
    else if (fAt(lo) < 0) rMax = 0;
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (fAt(m) >= 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      pos.push(hCyl + r * c, sliceZ + 0.02, r * s);
    }
  }
  let any = false;
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1); any = true;
  }
  if (!any) return;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  sliceMesh = addOrReplace(new THREE.Mesh(g, sliceMat), sliceMesh);
}

// ---------- axes ----------
function axisLine(from, to, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.12, gapSize: 0.08 })
    : new THREE.LineBasicMaterial({ color: 0x000000 });
  const l = new THREE.Line(g, mat);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}
function arrowHead(pos, dir, len = 0.16) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045, len, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  cone.position.copy(pos).addScaledVector(dir, -len / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
}

// x-axis (world +X, forward lower-left), y-axis (world +Z, right), z-axis (world +Y, up)
axisLine(M(0, 0, 0), M(2.9, 0, 0)); arrowHead(M(2.9, 0, 0), new THREE.Vector3(1, 0, 0));
axisLine(M(0, 0, 0), M(0, 0, 3.1)); arrowHead(M(0, 0, 3.1), new THREE.Vector3(0, 0, 1));
axisLine(M(0, 0, 0), M(0, 0, 3.9), true);                       // dashed inside solid
axisLine(M(0, 0, 3.9), M(0, 0, 4.55)); arrowHead(M(0, 0, 4.55), new THREE.Vector3(0, 1, 0));
// tick at x = 2
axisLine(M(2, 0, -0.06), M(2, 0, 0.06));

// annotation arrows (thin 3D lines/curve, black)
const capTarget = M(-0.4, 1.45, 1.5), capAnchor = M(-0.5, 1.95, 2.7);
axisLine(capAnchor, capTarget);
arrowHead(capTarget, capTarget.clone().sub(capAnchor).normalize(), 0.12);
const diskCurve3 = new THREE.QuadraticBezierCurve3(M(2.3, -1.5, 0.02), M(2.3, -0.7, 0.05), M(1.85, -0.42, 0.03));
const diskArrow = new THREE.Line(new THREE.BufferGeometry().setFromPoints(diskCurve3.getPoints(24)), new THREE.LineBasicMaterial({ color: 0x000000 }));
scene.add(diskArrow);
arrowHead(diskCurve3.getPoint(1), diskCurve3.getPoint(1).clone().sub(diskCurve3.getPoint(0.92)).normalize(), 0.12);

