  // bright rim at open top
  const rp = [];
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    rp.push(new THREE.Vector3(x, Math.max(0.001, capFn(x, y)), y));
  }
  rimLine = addOrReplace(new THREE.Line(rp.length ? new THREE.BufferGeometry().setFromPoints(rp) : new THREE.BufferGeometry(), rimMat), rimLine);
}

// ---------- intersection curve ----------
function buildCurve() {
  const pts = [];
  for (let i = 0; i < 128; i++) {
    const t = (i / 128) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    const z = capFn(x, y);
    if (z > 0) pts.push(new THREE.Vector3(x, z, y));
  }
  const g = pts.length > 2 ? new THREE.BufferGeometry().setFromPoints(pts) : new THREE.BufferGeometry();
  curveLine = addOrReplace(new THREE.LineLoop(g, curveMat), curveLine);
}

// ---------- base disk ----------
function buildDisk() {
  const g = new THREE.CircleGeometry(1, 72);
  g.rotateX(-Math.PI / 2); // lie in world XZ (math xy-plane)
  const m = new THREE.Mesh(g, diskMat);
  m.position.set(hCyl, 0.005, 0);
  diskMesh = addOrReplace(m, diskMesh);
}

function rebuildAll() {
  buildCap(); buildWall(); buildCurve(); buildDisk(); buildSlice();
  updateVisibility();
}

// ---------- slice cross-section ----------
let sliceZ = 0;
function buildSlice() {
  if (sliceMesh) { scene.remove(sliceMesh); _disposeObject(sliceMesh); sliceMesh = null; }
  if (sliceZ <= 0) return;
  const NR = 48, NT = 144;
  const pos = [], idx = [];
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    // bisect radius where capFn = sliceZ along this ray (from disk center)
    let lo = 0, hi = 1, rMax = 1;
    const fAt = (r) => capFn(hCyl + r * c, r * s) - sliceZ;
    if (fAt(hi) >= 0) rMax = hi;
    else if (fAt(lo) < 0) rMax = 0;
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (fAt(m) >= 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      pos.push(hCyl + r * c, sliceZ + 0.02, r * s);
    }
  }
  let any = false;
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1); any = true;
  }
  if (!any) return;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  sliceMesh = addOrReplace(new THREE.Mesh(g, sliceMat), sliceMesh);
}

