Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Bounding surface
  <select id="selSurface">
    <option value="All" selected>All</option>
    <option value="cap">Paraboloid cap</option>
    <option value="wall">Cylinder wall</option>
    <option value="disk">Base disk</option>
    <option value="curve">Intersection curve</option>
  </select>
</label>
<label>Slice height z <span id="sliceVal">0.00</span>
  <input type="range" id="sliceHeight" min="0" max="3" step="0.05" value="0">
</label>
<label>View
  <select id="selView">
    <option value="region">Base region</option>
    <option value="solid" selected>Capped solid</option>
  </select>
</label>
<label>cap z = <input type="text" id="capEq" value="4 - x*x - y*y" style="width:130px"></label>
<label>cylinder (x − h)² + y² = 1, h = <input type="text" id="cylEq" value="1" style="width:60px"></label>
<div style="display:flex;gap:4px;">
  <button id="btnPrev">◀ Step</button>
  <button id="btnNext">Step ▶</button>
</div>
<div id="stepNarration" style="font-size:11px;max-width:220px;color:#333;background:#fff;padding:4px;border:1px solid #ddd;border-radius:4px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Element spec:
// paraboloid cap → custom radial BufferGeometry, vertex colors blue(#5b8fc4)→orange(#d2691e) by height
// cylinder wall → custom parametric grid, FULL height (0 → zTop where zTop is above the
//                 intersection, i.e. the tube protrudes through the cap as in the source),
//                 vertex colors blue→orange height gradient (same palette as cap), double-sided
// open top rim  → THREE.Line loop at zTop, bright blue
// intersection curve → THREE.LineLoop, z = capFn(h+cos t, sin t), color #cc3300
// base disk → CircleGeometry r=1 at (h,0), flat #4f86c6, in xy-plane (world XZ)
// axes → black Lines + ConeGeometry arrowheads; z = world Y, math (x,y,z) → world (x, z, y)
// dashed z-axis inside solid → LineDashedMaterial 0→cap(0,0); solid above with arrowhead
// slice → translucent lens mesh (polar grid clipped by fn>=z), color #e0a030
// labels → addLabel: x, y (at tip of y-axis arrow), z, 0, 2, z = 4-x²-y² (3D arrow), (x-h)²+y²=1 (curved 3D arrow)

const M = (x, y, z) => new THREE.Vector3(x, z, y); // math → world (y-up)
let capFn = (x, y) => 4 - x * x - y * y;
let hCyl = 1;

scene.add(new THREE.AmbientLight(0xffffff, 0.7));
const dirLight = new THREE.DirectionalLight({ color: 0xffffff }.color, 1.0);
dirLight.position.set(3, 6, 4);
scene.add(dirLight);

const C_BLUE = new THREE.Color(0x5b8fc4), C_ORANGE = new THREE.Color(0xd2691e);

// ---------- materials ----------
const capMat = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide, transparent: true });
const wallMat = new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.72, side: THREE.DoubleSide, depthWrite: false });
const diskMat = new THREE.MeshLambertMaterial({ color: 0x4f86c6, transparent: true, opacity: 0.95, side: THREE.DoubleSide });
const curveMat = new THREE.LineBasicMaterial({ color: 0xcc3300 });
const sliceMat = new THREE.MeshBasicMaterial({ color: 0xe0a030, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false });
const rimMat = new THREE.LineBasicMaterial({ color: 0x2f6fb4 });

let capMesh = null, wallMesh = null, curveLine = null, diskMesh = null, rimLine = null, sliceMesh = null;

function addOrReplace(obj, prev) {
  if (prev) { scene.remove(prev); _disposeObject(prev); }
  scene.add(obj);
  return obj;
}

// Top of the tube: above the highest point of the intersection curve so the
// cylinder visibly rises through the cap (as in the source). Slightly above
// cap(0,0) so it always protrudes; clamped to keep the figure framed.
function wallTop() {
  return Math.max(0.6, Math.min(4.6, capFn(0, 0) + 0.55));
}

// ---------- cap ----------
function buildCap() {
  const z0 = capFn(0, 0);
  if (!(z0 > 0)) { if (capMesh) { scene.remove(capMesh); _disposeObject(capMesh); capMesh = null; } return; }
  const NT = 96, NR = 40;
  const pos = [], col = [], idx = [];
  const tmpC = new THREE.Color();
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    // bisect for r where fn = 0 along this ray
    let lo = 0, hi = 3.0, rMax = 3.0;
    if (capFn(hi * c, hi * s) > 0) { rMax = hi; }
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (capFn(m * c, m * s) > 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      const x = r * c, y = r * s;
      const z = Math.max(0, capFn(x, y));
      pos.push(x, z, y);
      tmpC.copy(C_BLUE).lerp(C_ORANGE, Math.min(1, z / z0));
      col.push(tmpC.r, tmpC.g, tmpC.b);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  capMesh = addOrReplace(new THREE.Mesh(g, capMat), capMesh);
  registerInteractive(capMesh, { title: 'Paraboloid cap', body: 'z = 4 − x² − y² forms the top boundary of the solid. Its crown is at (0,0,4); the skirt meets the xy-plane on the circle x² + y² = 4.' });
}

// ---------- cylinder wall (FULL height — protrudes through the cap) ----------
function buildWall() {
  const NT = 96, NZ = 24;
  const zTop = wallTop();
  const z0 = Math.max(0.001, capFn(0, 0));
  const pos = [], col = [], idx = [];
  const tmpC = new THREE.Color();
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    for (let j = 0; j <= NZ; j++) {
      const z = zTop * (j / NZ);
      pos.push(x, z, y);
      // same blue→orange height gradient as the cap (source colors the tube identically)
      tmpC.copy(C_BLUE).lerp(C_ORANGE, Math.min(1, z / z0));
      col.push(tmpC.r, tmpC.g, tmpC.b);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NZ; j++) {
    const a = i * (NZ + 1) + j, b = a + NZ + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  wallMesh = addOrReplace(new THREE.Mesh(g, wallMat), wallMesh);
  wallMesh.renderOrder = 2; // draw after cap so translucency blends correctly
  registerInteractive(wallMesh, { title: 'Cylinder wall', body: 'The vertical cylinder (x − h)² + y² = 1 extrudes the base disk upward and rises through the paraboloid; cap and wall meet along the closed intersection curve.' });

  // bright rim at the open top
  const rp = [];
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    rp.push(new THREE.Vector3(hCyl + Math.cos(t), zTop, Math.sin(t)));
  }
  rimLine = addOrReplace(new THREE.Line(new THREE.BufferGeometry().setFromPoints(rp), rimMat), rimLine);
}

// ---------- intersection curve ----------
function buildCurve() {
  const pts = [];
  for (let i = 0; i < 128; i++) {
    const t = (i / 128) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    const z = capFn(x, y);
    if (z > 0) pts.push(new THREE.Vector3(x, z, y));
  }
  const g = pts.length > 2 ? new THREE.BufferGeometry().setFromPoints(pts) : new THREE.BufferGeometry();
  curveLine = addOrReplace(new THREE.LineLoop(g, curveMat), curveLine);
  registerInteractive(curveLine, { title: 'Intersection curve', body: 'Where wall meets cap: substituting x² + y² = 2hx into the cap gives the top rim of the solid (for h = 1, z = 4 − 2x).' });
}

// ---------- base disk ----------
function buildDisk() {
  const g = new THREE.CircleGeometry(1, 72);
  g.rotateX(-Math.PI / 2); // lie in world XZ (math xy-plane)
  const m = new THREE.Mesh(g, diskMat);
  m.position.set(hCyl, 0.005, 0);
  diskMesh = addOrReplace(m, diskMesh);
  registerInteractive(diskMesh, { title: 'Base region', body: 'The disk (x − h)² + y² ≤ 1 in the xy-plane is the region of integration. It touches the origin and reaches x = h + 1.' });
}

function rebuildAll() {
  buildCap(); buildWall(); buildCurve(); buildDisk(); buildSlice();
  updateVisibility();
}

// ---------- slice cross-section ----------
let sliceZ = 0;
function buildSlice() {
  if (sliceMesh) { scene.remove(sliceMesh); _disposeObject(sliceMesh); sliceMesh = null; }
  if (sliceZ <= 0) return;
  const NR = 48, NT = 144;
  const pos = [], idx = [];
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    // bisect radius where capFn = sliceZ along this ray (from disk center)
    let lo = 0, hi = 1, rMax = 1;
    const fAt = (r) => capFn(hCyl + r * c, r * s) - sliceZ;
    if (fAt(hi) >= 0) rMax = hi;
    else if (fAt(lo) < 0) rMax = 0;
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (fAt(m) >= 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      pos.push(hCyl + r * c, sliceZ + 0.02, r * s);
    }
  }
  let any = false;
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1); any = true;
  }
  if (!any) return;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  sliceMesh = addOrReplace(new THREE.Mesh(g, sliceMat), sliceMesh);
}

// ---------- axes ----------
function axisLine(from, to, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.12, gapSize: 0.08 })
    : new THREE.LineBasicMaterial({ color: 0x000000 });
  const l = new THREE.Line(g, mat);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}
function arrowHead(pos, dir, len = 0.16) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045, len, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  cone.position.copy(pos).addScaledVector(dir, -len / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
}

// x-axis (world +X, forward lower-left), y-axis (world +Z, right), z-axis (world +Y, up)
axisLine(M(0, 0, 0), M(2.9, 0, 0)); arrowHead(M(2.9, 0, 0), new THREE.Vector3(1, 0, 0));
axisLine(M(0, 0, 0), M(0, 0, 3.4)); arrowHead(M(0, 0, 3.4), new THREE.Vector3(0, 0, 1));
axisLine(M(0, 0, 0), M(0, 0, 3.9), true);                       // dashed inside solid
axisLine(M(0, 0, 3.9), M(0, 0, 4.55)); arrowHead(M(0, 0, 4.55), new THREE.Vector3(0, 1, 0));
// tick at x = 2
axisLine(M(2, 0, -0.06), M(2, 0, 0.06));

// annotation arrows (thin 3D lines/curve, black)
const capTarget = M(-0.4, 1.45, 1.5), capAnchor = M(-0.5, 1.95, 2.7);
axisLine(capAnchor, capTarget);
arrowHead(capTarget, capTarget.clone().sub(capAnchor).normalize(), 0.12);
const diskCurve3 = new THREE.QuadraticBezierCurve3(M(2.3, -1.5, 0.02), M(2.3, -0.7, 0.05), M(1.85, -0.42, 0.03));
const diskArrow = new THREE.Line(new THREE.BufferGeometry().setFromPoints(diskCurve3.getPoints(24)), new THREE.LineBasicMaterial({ color: 0x000000 }));
scene.add(diskArrow);
arrowHead(diskCurve3.getPoint(1), diskCurve3.getPoint(1).clone().sub(diskCurve3.getPoint(0.92)).normalize(), 0.12);

// ---------- visibility / highlight ----------
const partOf = () => ({ cap: capMesh, wall: wallMesh, disk: diskMesh, curve: curveLine });
function updateVisibility() {
  const view = document.getElementById('selView').value;
  const sel = document.getElementById('selSurface').value;
  const parts = partOf();
  const solidMode = view === 'solid';
  for (const key of ['cap', 'wall', 'curve']) {
    const o = parts[key]; if (o) o.visible = solidMode;
  }
  if (parts.disk) parts.disk.visible = true;
  if (rimLine) rimLine.visible = solidMode;
  if (sliceMesh) sliceMesh.visible = solidMode && sliceZ > 0;
  if (!solidMode) { diskMat.opacity = 1; diskMat.emissive?.setHex(0x113355); return; }
  diskMat.emissive?.setHex(0x000000);
  const set = (obj, mat, baseOp, on) => {
    if (!obj) return;
    mat.transparent = true;
    mat.opacity = on ? baseOp : 0.10;
    if (mat.emissive) mat.emissive.setHex(on && sel !== 'All' ? 0x333311 : 0x000000);
  };
  set(parts.cap, capMat, 1.0, sel === 'All' || sel === 'cap');
  set(parts.wall, wallMat, 0.72, sel === 'All' || sel === 'wall');
  set(parts.disk, diskMat, 0.95, sel === 'All' || sel === 'disk');
  curveMat.color.setHex(sel === 'All' || sel === 'curve' ? 0xcc3300 : 0xcccccc);
  rimMat.color.setHex(sel === 'All' || sel === 'wall' ? 0x2f6fb4 : 0xcccccc);
}

rebuildAll();

setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.7 });

// ---------- labels (after camera) ----------
addLabel('x', M(3.05, 0, 0), { bold: true, fontSize: '15px' });
addLabel('y', M(0, 0, 3.62), { bold: true, fontSize: '15px' });   // at the tip of the y-axis arrow
addLabel('z', M(0, 0, 4.75), { bold: true, fontSize: '15px' });
addLabel('0', M(0.14, 0, 0.28), { fontSize: '13px' });
addLabel('2', M(2.0, 0, -0.3), { fontSize: '13px' });
addLabel('z = 4 − x² − y²', capAnchor, { fontSize: '14px', offset: [55, -14], background: 'rgba(255,255,255,0.7)' });
