Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Bounding surface
  <select id="selSurface">
    <option value="All" selected>All</option>
    <option value="cap">Paraboloid cap</option>
    <option value="wall">Cylinder wall</option>
    <option value="disk">Base disk</option>
    <option value="curve">Intersection curve</option>
  </select>
</label>
<label>Slice height z <span id="sliceVal">0.00</span>
  <input type="range" id="sliceHeight" min="0" max="3" step="0.05" value="0">
</label>
<label>View
  <select id="selView">
    <option value="region">Base region</option>
    <option value="solid" selected>Capped solid</option>
  </select>
</label>
<label>cap z = <input type="text" id="capEq" value="4 - x*x - y*y" style="width:130px"></label>
<label>cylinder (x − h)² + y² = 1, h = <input type="text" id="cylEq" value="1" style="width:60px"></label>
<div style="display:flex;gap:4px;">
  <button id="btnPrev">◀ Step</button>
  <button id="btnNext">Step ▶</button>
</div>
<div id="stepNarration" style="font-size:11px;max-width:220px;color:#333;background:#fff;padding:4px;border:1px solid #ddd;border-radius:4px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Element spec:
// paraboloid cap → custom radial BufferGeometry, vertex colors blue(#5b8fc4)→orange(#d2691e) by height
// cylinder wall → custom parametric grid, FULL height (0 → zTop above the cap so the tube
//                 protrudes as in the source), nearly opaque (0.92, depthWrite on) so it reads
//                 solid; vertex colors blue→orange height gradient (same palette as cap)
// open top rim  → THREE.Line loop at zTop, bright blue
// intersection curve → THREE.LineLoop z = capFn(h+cos t, sin t), bright red #e02000 plus a
//                      second slightly-offset loop for extra visual weight
// base disk → CircleGeometry r=1 at (h,0), flat #4f86c6, in xy-plane (world XZ)
// axes → black Lines + ConeGeometry arrowheads; z = world Y, math (x,y,z) → world (x, z, y)
// dashed z-axis inside solid → prominent LineDashedMaterial (bigger dashes) 0→cap(0,0)
// slice → translucent lens mesh (polar grid clipped by fn>=z), color #e0a030
// labels → addLabel: x, y (at tip of rightward y-axis arrow, offset clear of z), z, 0, 2,
//          z = 4-x²-y² (3D arrow), (x-h)²+y²=1 (curved 3D arrow)

const M = (x, y, z) => new THREE.Vector3(x, z, y); // math → world (y-up)
let capFn = (x, y) => 4 - x * x - y * y;
let hCyl = 1;

scene.add(new THREE.AmbientLight(0xffffff, 0.7));
const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
dirLight.position.set(3, 6, 4);
scene.add(dirLight);

const C_BLUE = new THREE.Color(0x5b8fc4), C_ORANGE = new THREE.Color(0xd2691e);

// ---------- materials ----------
const capMat = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide, transparent: true });
// Wall nearly opaque with depth writing so it reads as a solid tube (source look)
const wallMat = new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.92, side: THREE.DoubleSide, depthWrite: true });
const diskMat = new THREE.MeshLambertMaterial({ color: 0x4f86c6, transparent: true, opacity: 0.95, side: THREE.DoubleSide });
const curveMat = new THREE.LineBasicMaterial({ color: 0xe02000 });
const curveMat2 = new THREE.LineBasicMaterial({ color: 0xe02000 });
const sliceMat = new THREE.MeshBasicMaterial({ color: 0xe0a030, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false });
const rimMat = new THREE.LineBasicMaterial({ color: 0x2f6fb4 });

let capMesh = null, wallMesh = null, curveLine = null, curveLine2 = null, diskMesh = null, rimLine = null, sliceMesh = null;

function addOrReplace(obj, prev) {
  if (prev) { scene.remove(prev); _disposeObject(prev); }
  scene.add(obj);
  return obj;
}

function wallTop() {
  return Math.max(0.6, Math.min(4.6, capFn(0, 0) + 0.55));
}

// ---------- cap ----------
function buildCap() {
  const z0 = capFn(0, 0);
  if (!(z0 > 0)) { if (capMesh) { scene.remove(capMesh); _disposeObject(capMesh); capMesh = null; } return; }
  const NT = 96, NR = 40;
  const pos = [], col = [], idx = [];
  const tmpC = new THREE.Color();
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    let lo = 0, hi = 3.0, rMax = 3.0;
    if (capFn(hi * c, hi * s) > 0) { rMax = hi; }
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (capFn(m * c, m * s) > 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      const x = r * c, y = r * s;
      const z = Math.max(0, capFn(x, y));
      pos.push(x, z, y);
      tmpC.copy(C_BLUE).lerp(C_ORANGE, Math.min(1, z / z0));
      col.push(tmpC.r, tmpC.g, tmpC.b);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  capMesh = addOrReplace(new THREE.Mesh(g, capMat), capMesh);
  registerInteractive(capMesh, { title: 'Paraboloid cap', body: 'z = 4 − x² − y² forms the top boundary of the solid. Its crown is at (0,0,4); the skirt meets the xy-plane on the circle x² + y² = 4.' });
}

// ---------- cylinder wall ----------
function buildWall() {
  const NT = 96, NZ = 24;
  const zTop = wallTop();
  const z0 = Math.max(0.001, capFn(0, 0));
  const pos = [], col = [], idx = [];
  const tmpC = new THREE.Color();
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    const x = hCyl + Math.cos(t), y = Math.sin(t);
    for (let j = 0; j <= NZ; j++) {
      const z = zTop * (j / NZ);
      pos.push(x, z, y);
      tmpC.copy(C_BLUE).lerp(C_ORANGE, Math.min(1, z / z0));
      col.push(tmpC.r, tmpC.g, tmpC.b);
    }
  }
  for (let i = 0; i < NT; i++) for (let j = 0; j < NZ; j++) {
    const a = i * (NZ + 1) + j, b = a + NZ + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  wallMesh = addOrReplace(new THREE.Mesh(g, wallMat), wallMesh);
  registerInteractive(wallMesh, { title: 'Cylinder wall', body: 'The vertical cylinder (x − h)² + y² = 1 extrudes the base disk upward and rises through the paraboloid; cap and wall meet along the closed intersection curve.' });

  const rp = [];
  for (let i = 0; i <= NT; i++) {
    const t = (i / NT) * Math.PI * 2;
    rp.push(new THREE.Vector3(hCyl + Math.cos(t), zTop, Math.sin(t)));
  }
  rimLine = addOrReplace(new THREE.Line(new THREE.BufferGeometry().setFromPoints(rp), rimMat), rimLine);
}

// ---------- intersection curve (drawn twice, slightly offset, for a bolder red ring) ----------
function buildCurve() {
  const mk = (dR) => {
    const pts = [];
    for (let i = 0; i < 128; i++) {
      const t = (i / 128) * Math.PI * 2;
      const rr = 1 + dR;
      const x = hCyl + rr * Math.cos(t), y = rr * Math.sin(t);
      const z = capFn(x, y);
      if (z > 0) pts.push(new THREE.Vector3(x, z, y));
    }
    return pts.length > 2 ? new THREE.BufferGeometry().setFromPoints(pts) : new THREE.BufferGeometry();
  };
  curveLine = addOrReplace(new THREE.LineLoop(mk(0), curveMat), curveLine);
  curveLine2 = addOrReplace(new THREE.LineLoop(mk(0.015), curveMat2), curveLine2);
  registerInteractive(curveLine, { title: 'Intersection curve', body: 'Where wall meets cap: substituting x² + y² = 2hx into the cap gives the top rim of the solid (for h = 1, z = 4 − 2x).' });
}

// ---------- base disk ----------
function buildDisk() {
  const g = new THREE.CircleGeometry(1, 72);
  g.rotateX(-Math.PI / 2);
  const m = new THREE.Mesh(g, diskMat);
  m.position.set(hCyl, 0.005, 0);
  diskMesh = addOrReplace(m, diskMesh);
  registerInteractive(diskMesh, { title: 'Base region', body: 'The disk (x − h)² + y² ≤ 1 in the xy-plane is the region of integration. It touches the origin and reaches x = h + 1.' });
}

function rebuildAll() {
  buildCap(); buildWall(); buildCurve(); buildDisk(); buildSlice();
  updateVisibility();
}

// ---------- slice cross-section ----------
let sliceZ = 0;
function buildSlice() {
  if (sliceMesh) { scene.remove(sliceMesh); _disposeObject(sliceMesh); sliceMesh = null; }
  if (sliceZ <= 0) return;
  const NR = 48, NT = 144;
  const pos = [], idx = [];
  for (let i = 0; i <= NT; i++) {
    const th = (i / NT) * Math.PI * 2;
    const c = Math.cos(th), s = Math.sin(th);
    let lo = 0, hi = 1, rMax = 1;
    const fAt = (r) => capFn(hCyl + r * c, r * s) - sliceZ;
    if (fAt(hi) >= 0) rMax = hi;
    else if (fAt(lo) < 0) rMax = 0;
    else { for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (fAt(m) >= 0) lo = m; else hi = m; } rMax = lo; }
    for (let j = 0; j <= NR; j++) {
      const r = rMax * (j / NR);
      pos.push(hCyl + r * c, sliceZ + 0.02, r * s);
    }
  }
  let any = false;
  for (let i = 0; i < NT; i++) for (let j = 0; j < NR; j++) {
    const a = i * (NR + 1) + j, b = a + NR + 1;
    idx.push(a, b, a + 1, b, b + 1, a + 1); any = true;
  }
  if (!any) return;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  sliceMesh = addOrReplace(new THREE.Mesh(g, sliceMat), sliceMesh);
}

// ---------- axes ----------
function axisLine(from, to, dashed) {
  const g = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.22, gapSize: 0.1 })
    : new THREE.LineBasicMaterial({ color: 0x000000 });
  const l = new THREE.Line(g, mat);
  if (dashed) l.computeLineDistances();
  scene.add(l);
  return l;
}
function arrowHead(pos, dir, len = 0.16) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045, len, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  cone.position.copy(pos).addScaledVector(dir, -len / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
}

// x-axis (world +X), y-axis (world +Z, right), z-axis (world +Y, up)
axisLine(M(0, 0, 0), M(2.9, 0, 0)); arrowHead(M(2.9, 0, 0), new THREE.Vector3(1, 0, 0));
axisLine(M(0, 0, 0), M(0, 0, 3.4)); arrowHead(M(0, 0, 3.4), new THREE.Vector3(0, 0, 1));
axisLine(M(0, 0, 0), M(0, 0, 3.9), true);                       // prominent dashed interior z-axis
axisLine(M(0, 0, 3.9), M(0, 0, 4.55)); arrowHead(M(0, 0, 4.55), new THREE.Vector3(0, 1, 0));
axisLine(M(2, 0, -0.06), M(2, 0, 0.06));                        // tick at x = 2

// annotation arrows
const capTarget = M(-0.4, 1.45, 1.5), capAnchor = M(-0.5, 1.95, 2.7);
axisLine(capAnchor, capTarget);
arrowHead(capTarget, capTarget.clone().sub(capAnchor).normalize(), 0.12);
const diskCurve3 = new THREE.QuadraticBezierCurve3(M(2.3, -1.5, 0.02), M(2.3, -0.7, 0.05), M(1.85, -0.42, 0.03));
const diskArrow = new THREE.Line(new THREE.BufferGeometry().setFromPoints(diskCurve3.getPoints(24)), new THREE.LineBasicMaterial({ color: 0x000000 }));
scene.add(diskArrow);
arrowHead(diskCurve3.getPoint(1), diskCurve3.getPoint(1).clone().sub(diskCurve3.getPoint(0.92)).normalize(), 0.12);

// ---------- visibility / highlight ----------
const partOf = () => ({ cap: capMesh, wall: wallMesh, disk: diskMesh, curve: curveLine });
function updateVisibility() {
  const view = document.getElementById('selView').value;
  const sel = document.getElementById('selSurface').value;
  const parts = partOf();
  const solidMode = view === 'solid';
  for (const key of ['cap', 'wall', 'curve']) {
    const o = parts[key]; if (o) o.visible = solidMode;
  }
  if (curveLine2) curveLine2.visible = solidMode;
  if (parts.disk) parts.disk.visible = true;
  if (rimLine) rimLine.visible = solidMode;
  if (sliceMesh) sliceMesh.visible = solidMode && sliceZ > 0;
  if (!solidMode) { diskMat.opacity = 1; diskMat.emissive?.setHex(0x113355); return; }
  diskMat.emissive?.setHex(0x000000);
  const set = (obj, mat, baseOp, on) => {
    if (!obj) return;
    mat.transparent = true;
    mat.opacity = on ? baseOp : 0.10;
    if (mat.emissive) mat.emissive.setHex(on && sel !== 'All' ? 0x333311 : 0x000000);
  };
  set(parts.cap, capMat, 1.0, sel === 'All' || sel === 'cap');
  set(parts.wall, wallMat, 0.92, sel === 'All' || sel === 'wall');
  set(parts.disk, diskMat, 0.95, sel === 'All' || sel === 'disk');
  const cc = sel === 'All' || sel === 'curve' ? 0xe02000 : 0xcccccc;
  curveMat.color.setHex(cc); curveMat2.color.setHex(cc);
  rimMat.color.setHex(sel === 'All' || sel === 'wall' ? 0x2f6fb4 : 0xcccccc);
}

rebuildAll();

setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.7 });

// ---------- labels ----------
addLabel('x', M(3.05, 0, 0), { bold: true, fontSize: '15px' });
// y label pinned to the rightward y-axis arrow tip, pushed right so it never collides with z
addLabel('y', M(0, 0, 3.45), { bold: true, fontSize: '15px', offset: [16, 4] });
addLabel('z', M(0, 0, 4.75), { bold: true, fontSize: '15px' });
addLabel('0', M(0.14, 0, 0.28), { fontSize: '13px' });
addLabel('2', M(2.0, 0, -0.3), { fontSize: '13px' });
addLabel('z = 4 − x² − y²', capAnchor, { fontSize: '14px', offset: [55, -14], background: 'rgba(255,255,255,0.7)' });
addLabel('(x − 1)² + y² = 1', M(2.35, -1.55, 0), { fontSize: '14px', offset: [10, 26], background: 'rgba(255,255,255,0.7)' });

// ---------- interactivity ----------
document.getElementById('selSurface').addEventListener('change', updateVisibility);
document.getElementById('selView').addEventListener('change', updateVisibility);
document.getElementById('sliceHeight').addEventListener('input', (e) => {
  sliceZ = parseFloat(e.target.value);
  document.getElementById('sliceVal').textContent = sliceZ.toFixed(2);
  buildSlice(); updateVisibility();
});

bindEquationInput('capEq', (fn) => { capFn = fn; rebuildAll(); }, { variables: ['x', 'y'] });
bindEquationInput('cylEq', (fn) => { const v = fn(); if (Number.isFinite(v) && v >= 0 && v <= 2) { hCyl = v; rebuildAll(); } }, { variables: [] });

// ---------- demo steps ----------
const STEPS = [
  { title: 'Base region', narration: 'Start with just the disk (x − 1)² + y² = 1 in the xy-plane, centered at (1,0) with radius 1 — it touches the origin and reaches the tick at x = 2. This is the region of integration.', state: { regionVsSolid: 'region', boundingSurface: 'disk', sliceHeight: 0 } },
  { title: 'Extrude to the cap', narration: 'Switch to the capped solid: the disk rises as a vertical cylinder, its wall piercing the paraboloid z = 4 − x² − y² along a closed curve. The solid lives below the cap and inside the wall.', state: { regionVsSolid: 'solid', boundingSurface: 'All', sliceHeight: 0 } },
  { title: 'Sweep a slice upward', narration: 'Raise the slice from z = 0 toward z = 3. Near the base the cross-section is the full disk; as z climbs, the paraboloid clips it on the side nearer the origin, so slices shrink — their accumulation is the volume.', state: { regionVsSolid: 'solid', boundingSurface: 'All', sliceHeight: 2.5 } },
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  document.getElementById('selView').value = s.state.regionVsSolid;
  document.getElementById('selSurface').value = s.state.boundingSurface;
  sliceZ = s.state.sliceHeight;
  document.getElementById('sliceHeight').value = sliceZ;
  document.getElementById('sliceVal').textContent = sliceZ.toFixed(2);
  buildSlice(); updateVisibility();
  document.getElementById('stepNarration').innerHTML = '<b>' + s.title + '.</b> ' + s.narration;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx <= 0 ? 0 : stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(1);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
